function allIcons() {
    return icons.slice(0)
}

function filteredIcons(query) {
    if (!query || query.length === 0)
        return allIcons()

    var needle = query.toLowerCase().trim()
    var results = []

    for (var index = 0; index < icons.length; ++index) {
        var icon = icons[index]
        if (icon.searchText.indexOf(needle) !== -1)
            results.push(icon)
    }

    return results
}
